import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    k = int(data[0])
    q = int(data[1])
    p = 2
    ops = []
    vals = []
    for _ in range(q):
        t = data[p]
        p += 1
        if t == 'ADD':
            x = int(data[p])
            p += 1
            ops.append(x)
            vals.append(x)
        else:
            ops.append(-1)
    uniq = sorted(set(vals))
    idx = {v: i + 1 for i, v in enumerate(uniq)}
    m = len(uniq)
    tree = [0] * (m + 1)
    top = 1
    while top * 2 <= m:
        top *= 2

    def upd(i, d):
        while i <= m:
            tree[i] += d
            i += i & -i

    def kth(kk):
        pos = 0
        b = top
        while b:
            np_ = pos + b
            if np_ <= m and tree[np_] < kk:
                pos = np_
                kk -= tree[np_]
            b >>= 1
        return uniq[pos]

    window = deque()
    out = []
    for x in ops:
        if x >= 0:
            window.append(x)
            upd(idx[x], 1)
            if len(window) > k:
                upd(idx[window.popleft()], -1)
        elif not window:
            out.append(-1)
        else:
            w = len(window)
            if w % 2:
                out.append(kth((w + 1) // 2))
            else:
                out.append((kth(w // 2) + kth(w // 2 + 1)) // 2)
    print('\n'.join(map(str, out)))

main()

