             fmt(2, ['ADD 0', 'ADD 1', 'MEDIAN', 'ADD 1000000000', 'MEDIAN']),
             fmt(5, ['ADD 3', 'ADD 3', 'ADD 3', 'MEDIAN'])]
    for _ in range(12):
        q = rng.randint(5, 40)
        k = rng.choice([1, 2, 3, 4, 5, 8, 50])
